style.css:
/* Stylish Khan Website Background */
body {
  margin: 0;
  min-height: 100vh;
  font-family: "Poppins", sans-serif;
  color: #fff;

  background:
    radial-gradient(circle at 20% 20%, rgba(255, 193, 7, 0.18), transparent 30%),
    radial-gradient(circle at 80% 70%, rgba(108, 92, 231, 0.20), transparent 35%),
    linear-gradient(135deg, #080b16, #111827 50%, #070914);

  background-size: 200% 200%;
  animation: backgroundMove 12s ease infinite;
  overflow-x: hidden;
}

/* Soft glowing overlay */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;

  background:
    linear-gradient(
      120deg,
      transparent 0%,
      rgba(255, 215, 100, 0.04) 45%,
      transparent 70%
    );

  animation: shine 8s linear infinite;
}

/* Background animation */
@keyframes backgroundMove {
  0% {
    background-position: 0% 50%;
  }

  50% {
    background-position: 100% 50%;
  }

  100% {
    background-position: 0% 50%;
  }
}

@keyframes shine {
  0% {
    transform: translateX(-100%);
  }

  100% {
    transform: translateX(100%);
  }
}

/* Optional Khan heading */
h1 {
  color: #ffd166;
  text-shadow:
    0 0 10px rgba(255, 209, 102, 0.5),
    0 0 30px rgba(255, 209, 102, 0.2);
}
